rename_count = 0
for file_info in files_to_rename:
    old_path = file_info['old_path']
    new_path = file_info['new_path']

    try:
        apis.file_system.move_file(access_token=token, source_file_path=old_path, destination_file_path=new_path, retain_dates=True)
        rename_count += 1
        if rename_count % 10 == 0:
            print(f"Renamed {rename_count} files...")
    except Exception as e:
        print(f"Error renaming {old_path}: {e}")

print(f"Total files renamed: {rename_count}")

