action.code:
# Get all liked albums and collect all songs from them
all_album_songs = set()
page_index = 0
while True:
    liked_albums = apis.spotify.show_liked_albums(access_token=access_token, page_index=page_index)
    if not liked_albums:
        break
    for album in liked_albums:
        for song_id in album['song_ids']:
            all_album_songs.add(song_id)
    page_index += 1

print(f"Total unique songs from liked albums: {len(all_album_songs)}")

# Get all songs from all playlists
all_playlist_songs = set()
for playlist in all_playlists:
    for song_id in playlist['song_ids']:
        all_playlist_songs.add(song_id)

print(f"Total unique songs from all playlists: {len(all_playlist_songs)}")

