# Now I need to get details for all songs to check their genres and play counts
# First, let me collect all unique song IDs from liked songs, albums, and playlists

all_song_ids = set()

# From liked songs
for song in liked_songs:
    all_song_ids.add(song['song_id'])

# From liked albums
for album in liked_albums:
    for song_id in album['song_ids']:
        all_song_ids.add(song_id)

# From playlists
for playlist in playlists:
    for song_id in playlist['song_ids']:
        all_song_ids.add(song_id)

print(f"Total unique song IDs: {len(all_song_ids)}")
print(f"Sample song IDs: {list(all_song_ids)[:10]}")
